#!/bin/sh
# Generated by HyperThemes for lazyspotify.
#
# lazyspotify is a terminal client: it takes its colours from the terminal's
# 16-colour palette. This launcher opens it in a kitty window carrying the
# HyperThemes palette, falls back to foot's themed config, and finally to the
# current terminal.
if command -v kitty >/dev/null 2>&1; then
  exec kitty \
    -o background=#{{background}} \
    -o foreground=#{{onBackground}} \
    -o cursor=#{{primary}} \
    -o cursor_text_color=#{{onPrimary}} \
    -o selection_background=#{{primary}} \
    -o selection_foreground=#{{onPrimary}} \
    -o color0=#{{term0}} \
    -o color8=#{{term8}} \
    -o color1=#{{term1}} \
    -o color9=#{{term9}} \
    -o color2=#{{term2}} \
    -o color10=#{{term10}} \
    -o color3=#{{term3}} \
    -o color11=#{{term11}} \
    -o color4=#{{term4}} \
    -o color12=#{{term12}} \
    -o color5=#{{term5}} \
    -o color13=#{{term13}} \
    -o color6=#{{term6}} \
    -o color14=#{{term14}} \
    -o color7=#{{term7}} \
    -o color15=#{{term15}} \
    -e lazyspotify "$@"
fi

if command -v foot >/dev/null 2>&1 && [ -f "$HOME/.config/foot/hyperthemes.ini" ]; then
  exec foot -c "$HOME/.config/foot/hyperthemes.ini" lazyspotify "$@"
fi

exec lazyspotify "$@"
